import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireBlocks Configurator Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireBlocksConfigurator/aireblocks-configurator-v1-2-0.md","filePath":"aireblock-releases/AireBlocksConfigurator/aireblocks-configurator-v1-2-0.md","lastUpdated":1793188062000}`),a={name:`aireblock-releases/AireBlocksConfigurator/aireblocks-configurator-v1-2-0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireblocks-configurator-release-notes" tabindex="-1"><span class="fsc-product"><img src="/AireBlocks_Favicon.png"> AireBlocks Configurator Release Notes</span> <a class="header-anchor" href="#aireblocks-configurator-release-notes" aria-label="Permalink to “AireBlocks Configurator Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.2.0<br><strong>Release Date:</strong> 4 November 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Environment-Specific Themes (SUITECONF-397)</li><li>Create SSH Keys in AireVault Secrets (SUITECONF-388)</li><li>Improved Search for AireVault Variables and Secrets (SUITECONF-410)</li><li>Refreshed AireAudit Log Screens (SUITECONF-413)</li><li>Actor Role Code in the Audit Log (SUITECONF-297)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Editing Secret Values Now Saves Correctly (SUITECONF-414)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="environment-specific-themes-suiteconf-397" tabindex="-1">Environment-Specific Themes (SUITECONF-397) <a class="header-anchor" href="#environment-specific-themes-suiteconf-397" aria-label="Permalink to “Environment-Specific Themes (SUITECONF-397)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Themes are now stored for each tenant environment, so changing a theme only updates the environment you are working in. Existing themes continue to apply until they are edited, at which point a separate copy is saved for that environment. Tenanted login pages use the production environment&#39;s theme.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can try out new colours and branding in a test environment without affecting what your live users see, and only apply changes to production when you&#39;re happy with them.</p></div><h4 id="create-ssh-keys-in-airevault-secrets-suiteconf-388" tabindex="-1">Create SSH Keys in AireVault Secrets (SUITECONF-388) <a class="header-anchor" href="#create-ssh-keys-in-airevault-secrets-suiteconf-388" aria-label="Permalink to “Create SSH Keys in AireVault Secrets (SUITECONF-388)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>SSH keys can now be created and stored directly as AireVault secrets from the configurator.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can create and keep SSH keys alongside your other secrets in AireVault, without needing a separate tool to generate and store them. You can also rotate ssh keys quickly and easily by editing an existing secret.</p></div><h4 id="improved-search-for-airevault-variables-and-secrets-suiteconf-410" tabindex="-1">Improved Search for AireVault Variables and Secrets (SUITECONF-410) <a class="header-anchor" href="#improved-search-for-airevault-variables-and-secrets-suiteconf-410" aria-label="Permalink to “Improved Search for AireVault Variables and Secrets (SUITECONF-410)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Searching AireVault variables and secrets now runs on the server rather than in the browser, so results cover the full list rather than only the items already loaded.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Finding the variable or secret you need is more reliable, even when you have a large number of them.</p></div><h4 id="refreshed-aireaudit-log-screens-suiteconf-413" tabindex="-1">Refreshed AireAudit Log Screens (SUITECONF-413) <a class="header-anchor" href="#refreshed-aireaudit-log-screens-suiteconf-413" aria-label="Permalink to “Refreshed AireAudit Log Screens (SUITECONF-413)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The AireAudit log screens have been updated with a refreshed user interface.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Reviewing audit activity is clearer and more consistent with the rest of the platform.</p></div><h4 id="actor-role-code-in-the-audit-log-suiteconf-297" tabindex="-1">Actor Role Code in the Audit Log (SUITECONF-297) <a class="header-anchor" href="#actor-role-code-in-the-audit-log-suiteconf-297" aria-label="Permalink to “Actor Role Code in the Audit Log (SUITECONF-297)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The audit log now shows the role code of the person (actor) who carried out each recorded action.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can see the role each person was acting in when they made a change, making it easier to review activity and answer governance questions.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="editing-secret-values-now-saves-correctly-suiteconf-414" tabindex="-1">Editing Secret Values Now Saves Correctly (SUITECONF-414) <a class="header-anchor" href="#editing-secret-values-now-saves-correctly-suiteconf-414" aria-label="Permalink to “Editing Secret Values Now Saves Correctly (SUITECONF-414)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where editing an existing secret&#39;s value and saving it showed a &quot;Failed to update secret&quot; error, and the change was not saved.</p></div>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};